import React from 'react';
import './Products.css';

const Products = () => {
  const structures = [
    {
      name: "TENSILE STRUCTURES",
      description: "Lightweight membrane structures for large span coverage with minimal support.",
      features: ["Membrane Technology", "Cable Systems", "Minimal Support", "Weather Resistant"]
    },
    {
      name: "GERMAN HANGARS",
      description: "Precision-engineered aircraft hangars with German manufacturing standards.",
      features: ["Steel Framework", "Clear Span Design", "Bi-fold Doors", "Climate Control"]
    },
    {
      name: "INDUSTRIAL TENTS",
      description: "Temporary and permanent industrial shelter solutions for various applications.",
      features: ["Modular Design", "Quick Assembly", "Heavy Duty Frame", "Custom Sizing"]
    },
    {
      name: "ARCHITECTURAL CANOPIES",
      description: "Custom canopy solutions for commercial and public spaces.",
      features: ["Weather Protection", "Aesthetic Design", "Durable Materials", "Low Maintenance"]
    }
  ];

  return (
    <section className="structures section" id="structures">
      <div className="container">
        <h2 className="section-title">STRUCTURAL SOLUTIONS</h2>

        <div className="structures-grid">
          {structures.map((structure, index) => (
            <div key={index} className="structure-card">
              <h3 className="structure-name">{structure.name}</h3>
              <p className="structure-description">{structure.description}</p>
              <ul className="structure-features">
                {structure.features.map((feature, idx) => (
                  <li key={idx}>{feature}</li>
                ))}
              </ul>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default Products;
